import calendar
from datetime import date, timedelta

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        step = timedelta(days=k)
        cur = start_date
        for _ in range(count):
            result.append(cur.isoformat())
            cur += step
        return result

    if freq == "WEEKLY":
        target_wds = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        week_idx = 0
        while len(result) < count:
            monday = week0_monday + timedelta(days=7 * week_idx)
            for wd in target_wds:
                d = monday + timedelta(days=wd)
                if d >= start_date:
                    result.append(d.isoformat())
                    if len(result) == count:
                        return result
            week_idx += k
        return result

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        m_offset = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                y, m0 = divmod(base_months + m_offset, 12)
                mo = m0 + 1
                days_in_month = calendar.monthrange(y, mo)[1]
                day = days_in_month if target_day == -1 else target_day
                if 1 <= day <= days_in_month:
                    d = date(y, mo, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m_offset += k
        else:
            n = int(parts[2])
            target_wd = _WEEKDAYS[parts[3]]
            while len(result) < count:
                y, m0 = divmod(base_months + m_offset, 12)
                mo = m0 + 1
                first_wd, days_in_month = calendar.monthrange(y, mo)
                first_match = 1 + (target_wd - first_wd) % 7
                if n == -1:
                    day = first_match + 7 * ((days_in_month - first_match) // 7)
                else:
                    day = first_match + 7 * (n - 1)
                if day <= days_in_month:
                    d = date(y, mo, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m_offset += k
        return result

    if freq == "YEARLY":
        mm_str, dd_str = parts[2].split("-")
        mm, dd = int(mm_str), int(dd_str)
        year = start_date.year
        while len(result) < count:
            try:
                d = date(year, mm, dd)
            except ValueError:
                year += k
                continue
            if d >= start_date:
                result.append(d.isoformat())
            year += k
        return result

    raise ValueError(f"Unsupported rule: {rule}")
